package com.ruoyi.hexu;
import java.util.*;
import java.sql.Timestamp;
import static com.ruoyi.hexu.HexuStore.*;
import static com.ruoyi.hexu.BusinessException.require;

/** A group reserves one real SKU per member. Only successful payments count towards formation. */
public final class HexuGroupPurchase {
 private final HexuStore db;
 public HexuGroupPurchase(HexuStore db){this.db=db;}
 public void validate(long shop,Map<String,Object>b){require(!str(b,"name").trim().isEmpty(),"请填写拼团名称");if(!bool(b,"enabled"))return;require(number(b,"size")>=2&&number(b,"size")<=20,"成团人数须为2至20人");require(number(b,"hours")>=1&&number(b,"hours")<=168,"成团时限须为1至168小时");require(number(b,"startsAt")>=0&&number(b,"expiresAt")>number(b,"startsAt"),"拼团活动期限无效");Map<String,Object>sku=db.one("select * from hx_sku where shop_id=? and id=? and status='ACTIVE'",shop,str(b,"skuId"));require(number(sku,"min_qty")<=1&&number(b,"price")>0&&number(b,"price")<=number(sku,"retail"),"拼团须为可单件购买的在售商品，团价不能超出零售价");}
 public Map<String,Object> campaign(long shop,String id,boolean lock){Map<String,Object>d=db.one("select * from hx_document where shop_id=? and id=? and kind='group_campaign' and status='ACTIVE'"+(lock?" for update":""),shop,id);Map<String,Object>b=db.parse(d.get("body_json"));long now=System.currentTimeMillis();require(bool(b,"enabled")&&number(b,"startsAt")<=now&&number(b,"expiresAt")>now,"拼团活动未启用或已结束");b.put("campaignId",id);return b;}
 public Map<String,Object> plan(Actor a,long shop,Map<String,Object>b,boolean lock){String gid=str(b,"groupId"),cid=str(b,"groupCampaignId");if(gid.isEmpty()&&cid.isEmpty())return Collections.emptyMap();require(db.agent(a.id,shop)==null,"拼团使用普通零售价，不适用代理采购");require(str(b,"couponId").isEmpty()&&number(b,"points")==0,"拼团价包邮，不叠加优惠券和积分抵扣");Map<String,Object>p;if(!gid.isEmpty()){Map<String,Object>g=db.one("select * from hx_group_buy where id=? and shop_id=?"+(lock?" for update":""),gid,shop);require("FORMING".equals(str(g,"status"))&&((Timestamp)g.get("expires_at")).getTime()>System.currentTimeMillis(),"该团已结束");require(db.optional("select order_id from hx_group_member where group_id=? and member_id=?",gid,a.id)==null,"您已参与该团，请在我的订单查看");long reserved=db.jdbc().queryForObject("select count(*) from hx_group_member m join hx_order o on o.id=m.order_id where m.group_id=? and o.status not in ('CANCELLED','REFUNDED')",Long.class,gid);require(reserved<number(g,"target_size"),"该团名额已满，请稍后刷新或另开新团");p=db.parse(g.get("snapshot_json"));p.put("groupId",gid);p.put("groupExpiresAt",((Timestamp)g.get("expires_at")).getTime());}
 else{p=campaign(shop,cid,lock);p.put("groupExpiresAt",Math.min(number(p,"expiresAt"),System.currentTimeMillis()+number(p,"hours")*3600000L));}
 require(b.get("items") instanceof List&&((List<?>)b.get("items")).size()==1,"拼团每人仅限活动商品1件");Map<String,Object>line=(Map<String,Object>)((List<?>)b.get("items")).get(0);require(str(line,"id").equals(str(p,"skuId"))&&number(line,"qty")==1,"拼团每人仅限活动商品1件");return p;
 }
 public void attach(Actor a,long shop,String order,Map<String,Object>plan){if(plan.isEmpty())return;String gid=str(plan,"groupId");if(gid.isEmpty()){gid=id("PT");db.jdbc().update("insert into hx_group_buy(id,shop_id,campaign_id,leader_id,sku_id,target_size,price,status,expires_at,snapshot_json) values(?,?,?,?,?,?,?,'FORMING',?,?)",gid,shop,str(plan,"campaignId"),a.id,str(plan,"skuId"),number(plan,"size"),number(plan,"price"),new Timestamp(number(plan,"groupExpiresAt")),db.json(plan));}
 db.jdbc().update("insert into hx_group_member(group_id,member_id,order_id) values(?,?,?)",gid,a.id,order);db.jdbc().update("update hx_order set expires_at=case when expires_at>? then ? else expires_at end where id=?",new Timestamp(number(plan,"groupExpiresAt")),new Timestamp(number(plan,"groupExpiresAt")),order);db.audit(a,shop,"GROUP_JOIN",order,null,map("groupId",gid));}
 public Map<String,Object> lockForOrder(String order){Map<String,Object>m=db.optional("select group_id from hx_group_member where order_id=?",order);return m==null?null:db.one("select * from hx_group_buy where id=? for update",m.get("group_id"));}
 public void paymentAllowed(String order){Map<String,Object>g=lockForOrder(order);if(g==null)return;require("FORMING".equals(str(g,"status"))&&((Timestamp)g.get("expires_at")).getTime()>System.currentTimeMillis(),"拼团已结束，迟到支付需按渠道对账处理");}
 public void paid(String order){Map<String,Object>g=lockForOrder(order);if(g==null||!"FORMING".equals(str(g,"status")))return;long count=db.jdbc().queryForObject("select count(*) from hx_group_member m join hx_order o on o.id=m.order_id where m.group_id=? and o.status='PAID'",Long.class,g.get("id"));if(count>=number(g,"target_size")){db.jdbc().update("update hx_group_buy set status='FORMED',formed_at=CURRENT_TIMESTAMP where id=?",g.get("id"));for(Map<String,Object>m:db.jdbc().queryForList("select member_id,order_id from hx_group_member where group_id=?",g.get("id")))db.message(number(g,"shop_id"),number(m,"member_id"),"拼团成功，等待商家发货",str(m,"order_id"));db.audit(new Actor(0,true,true),number(g,"shop_id"),"GROUP_FORMED",str(g,"id"),null,map("paidMembers",count));}}
 public void fulfillmentAllowed(String order){Map<String,Object>m=db.optional("select g.status from hx_group_buy g join hx_group_member m on m.group_id=g.id where m.order_id=?",order);require(m==null||"FORMED".equals(str(m,"status")),"拼团未成功，不可发货、收货或手工售后；失败后系统自动退款");}
 public int expire(HexuOrderService orders){int count=0;for(Map<String,Object>candidate:db.jdbc().queryForList("select id from hx_group_buy where status='FORMING' and expires_at<=CURRENT_TIMESTAMP order by id limit 100")){Map<String,Object>g=db.one("select * from hx_group_buy where id=? for update",candidate.get("id"));if(!"FORMING".equals(str(g,"status")))continue;db.jdbc().update("update hx_group_buy set status='FAILED' where id=?",g.get("id"));for(Map<String,Object>m:db.jdbc().queryForList("select order_id from hx_group_member where group_id=? order by order_id",g.get("id"))){Map<String,Object>o=db.one("select * from hx_order where id=? for update",m.get("order_id"));if("UNPAID".equals(str(o,"status")))orders.cancelLocked(o);else if("PAID".equals(str(o,"status"))){Map<String,Object>l=db.one("select * from hx_order_line where order_id=?",o.get("id"));String rid=id("SH");db.jdbc().update("insert into hx_refund(id,order_id,line_id,shop_id,member_id,qty,amount,refund_type,status,reason,restock_qty,review_by,review_note) values(?,?,?,?,?,?,?,'GROUP_FAILED','APPROVED','拼团超时未成团',?,0,'系统按原订单自动全额退款')",rid,o.get("id"),l.get("id"),o.get("shop_id"),o.get("buyer_id"),l.get("qty"),o.get("total"),l.get("qty"));db.jdbc().update("insert into hx_group_refund(refund_id,status) values(?,'PENDING')",rid);db.message(number(o,"shop_id"),number(o,"buyer_id"),"拼团未成团，已进入原路退款流程",rid);}}
 db.audit(new Actor(0,true,true),number(g,"shop_id"),"GROUP_FAILED",str(g,"id"),g,null);count++;}return count;}
 private Map<String,Object> view(Actor a,Map<String,Object>g){Map<String,Object>out=map("id",g.get("id"),"campaignId",g.get("campaign_id"),"skuId",g.get("sku_id"),"status",g.get("status"),"targetSize",g.get("target_size"),"price",g.get("price"),"expiresAt",g.get("expires_at"),"formedAt",g.get("formed_at"));List<Map<String,Object>>members=new ArrayList<>();for(Map<String,Object>m:db.jdbc().queryForList("select m.member_id,o.id,o.status,n.name from hx_group_member m join hx_order o on o.id=m.order_id join hx_member n on n.id=m.member_id where m.group_id=? and o.status<>'CANCELLED' order by m.created_at",g.get("id"))){String name=str(m,"name");members.add(map("name",name.isEmpty()?"用户":name.substring(0,1)+"**","status",m.get("status"),"leader",number(m,"member_id")==number(g,"leader_id")));if(number(m,"member_id")==a.id)out.put("myOrderId",m.get("id"));}out.put("members",members);out.put("paidCount",members.stream().filter(m->Arrays.asList("PAID","SHIPPED","COMPLETED").contains(str(m,"status"))).count());return out;}
 public Map<String,Object> detail(Actor a,long shop,String id){db.member(a);db.shop(shop);return view(a,db.one("select * from hx_group_buy where id=? and shop_id=?",id,shop));}
 public Map<String,Object> list(Actor a,long shop){db.member(a);db.shop(shop);List<Map<String,Object>>campaigns=new ArrayList<>();for(Map<String,Object>d:db.jdbc().queryForList("select * from hx_document where shop_id=? and kind='group_campaign' and status='ACTIVE' order by created_at desc",shop)){try{Map<String,Object>p=campaign(shop,str(d,"id"),false);Map<String,Object>publicPlan=new LinkedHashMap<>();for(String key:Arrays.asList("campaignId","name","skuId","price","size","hours","expiresAt"))publicPlan.put(key,p.get(key));campaigns.add(publicPlan);}catch(BusinessException ignored){}}
 List<Map<String,Object>>groups=new ArrayList<>();for(Map<String,Object>g:db.jdbc().queryForList("select g.* from hx_group_buy g where g.shop_id=? and ((g.status='FORMING' and g.expires_at>CURRENT_TIMESTAMP) or exists(select 1 from hx_group_member m where m.group_id=g.id and m.member_id=?)) order by g.created_at desc limit 100",shop,a.id))groups.add(view(a,g));return map("campaigns",campaigns,"groups",groups);}
}
